P.QBANK = ["Che cosa mi mostra questo brano su chi è Dio?","Quale vecchia natura, centrata su di sé, questo brano porta alla luce in me?","Che cosa farei se lasciassi che Gesù regni in questa situazione?","Quale esempio mi dà Gesù qui?","Quale passo vuole che io compia oggi lo Spirito Santo attraverso questa Parola?","Perché le persone di questo brano hanno fallito? La radice era l’orgoglio o la paura?","In che modo questo brano mi aiuta a esercitarmi nel Wu Ji (rinuncia a sé stessi)?","In quale relazione posso mettere in pratica questo brano?","Che legame c’è tra questo brano e la richiesta del Padre nostro «Venga il tuo regno»?","Dammi un’immagine della vita di ogni giorno per capire il cuore di questo brano."];
P.QAUD = {"seeker":["Che cosa c’entra questo brano con la mia vita di oggi?","Non pratico ancora la fede cristiana. Che cosa potrebbero significare queste parole per me?","Dio esiste davvero? Quali ragioni ci sono per credere?","Perché la Bibbia dice che ogni persona ha bisogno di Gesù?","Sono sotto molta pressione. Quale aiuto concreto può darmi la Bibbia?","Che cosa significa qui la parola «peccato»? Riguarda anche me?","I cristiani parlano continuamente di «grazia». Che cos’è, spiegata in modo semplice?","Se voglio saperne di più, da dove comincio?"],"teen":["Che cosa c’entra questo brano con la mia vita di ogni giorno: scuola, amici, telefono?","Se questo brano fosse un messaggio di Dio solo per me, che cosa direbbe?","Lo fanno tutti. È strano non farlo? Che cosa dice la Bibbia?","Puoi spiegarmi questo brano con un videogioco o un film?","Che cosa c’è di sorprendente o poco conosciuto in questo brano?","La pressione prima degli esami è enorme. Quale forza mi dà questo brano?","Faccio fatica a perdonare qualcuno. Come mi aiuta questo brano?","Dio mi vede davvero? Perché io valgo l’amore?"],"kid":["Di che cosa parla questa storia? Me la puoi raccontare?","Che cosa ha fatto Dio in questa storia?","Gesù mi vuole bene? Come faccio a saperlo?","Chi è il più coraggioso in questa storia? Perché?","Come posso essere come le persone di questa storia?","Insegnami un versetto breve da imparare a memoria.","Ho litigato con il mio migliore amico. Che cosa farebbe Gesù?","Mi puoi insegnare una piccolissima preghiera?"]};
P.AUD2 = {"elder":{"q":["Che cosa dice questo brano in parole semplicissime?","Quale conforto dà questo brano alle persone anziane?","Il mio corpo si indebolisce. Come si prende cura di me Dio?","Spesso sento una grande solitudine. Che cosa mi dà questo brano?","Come posso trasmettere la mia fede ai miei figli e nipoti?","Ci sono cose che non riesco a lasciare andare. Come mi insegna questo brano ad affidarle al Signore?","Ho già una certa età. Che cosa posso ancora fare per Dio?","Scrivimi, per favore, una breve preghiera da presentare al Signore."],"fu":["Salute","Solitudine","Famiglia","Affidamento","Speranza","Preghiera"],"rw":["Hai letto tutto il libro di {nm}!","Giorno dopo giorno hai percorso tutta questa strada. Dio ricorda questa fedeltà, ed è un esempio per i più giovani."],"res":["Nessun problema, ci andiamo con calma. Rileggendo, tutto diventerà più chiaro.","Molto bene! Ricordi molto di questo capitolo.","Meraviglioso! La Parola di Dio vive nel tuo cuore."]},"single_parent":{"q":["Porto sulle spalle, senza aiuto, la responsabilità della famiglia. Quale conforto mi dà questo brano?","Non ne posso più e ho la sensazione di non dare abbastanza ai miei figli. Come mi vede Dio?","Come si prende cura Dio degli orfani e delle vedove, e che cosa significa per me?","I soldi sono molto pochi. Che cosa mi dà questo brano?","Mio figlio mi risponde male e ha emozioni fortissime. Che cosa devo fare?","Non so come dire a mio figlio che papà (o mamma) non è con noi.","Sento una grande solitudine. Come posso chiedere aiuto alla comunità o ai miei fratelli e sorelle nella fede?","Scrivimi, per favore, una breve preghiera da dire in cinque minuti."],"fu":["Stanchezza","Figli","Denaro","Chiedere aiuto","Speranza","Preghiera"],"rw":["Hai letto tutto il libro di {nm}!","Non è facile continuare a leggere la Bibbia quando si porta la famiglia da soli. Dio vede ogni tuo passo ed è con te."],"res":["Nessun problema, hai fatto del tuo meglio. Rileggilo quando avrai tempo.","Molto bene! Ricordi tanto, nonostante le tue giornate piene.","Meraviglioso! La Parola di Dio ti sostiene."]},"single":{"q":["Che cosa mi dice questo brano come persona single?","Sento solitudine. Che cosa mi dà questo brano?","Chi sono in Cristo e quanto valgo?","Come mi affido a Dio mentre aspetto?","Quale saggezza offre la Bibbia per le relazioni?","Come si possono mettere al servizio di Dio il tempo e le energie di una persona single?","Come costruisco buone relazioni nella comunità e con i miei amici?","Scrivimi, per favore, una breve preghiera per una persona single."],"fu":["Solitudine","Identità","Attesa","Relazioni","Senso della vita","Preghiera"],"rw":["Hai letto tutto il libro di {nm}!","Hai camminato senza compagnia, e davanti a Dio i tuoi giorni sono pieni e amati."],"res":["Nessun problema, ci andiamo con calma. Rileggendo, tutto diventerà più chiaro.","Molto bene! Hai colto l’essenziale di questo capitolo.","Eccellente! Continui con costanza, e la Parola di Dio mette radici in te."]},"parent":{"q":["Che cosa mi ricorda questo brano come genitore?","Mio figlio non mi ascolta e ha emozioni fortissime. Come devo reagire?","Come metto insieme fermezza e grazia?","Come parlo bene con un figlio adolescente?","Alzo spesso la voce con mio figlio e poi mi sento in colpa. Che cosa posso fare?","Come guido mio figlio a conoscere Dio, invece di limitarmi a portarlo in chiesa?","Il mio partner e io non siamo d’accordo sull’educazione. Che cosa dice questo brano?","Scrivimi, per favore, una breve preghiera di benedizione per mio figlio."],"fu":["Dialogo","Regole","Coscienza","Coppia","Fede","Preghiera"],"rw":["Hai letto tutto il libro di {nm}!","Leggere ogni giorno la Scrittura in mezzo al trambusto dell’educazione dei figli è il più bell’esempio che tu possa dare loro."],"res":["Nessun problema, ci andiamo con calma. Rileggilo quando ne avrai l’occasione.","Molto bene! Hai colto l’essenziale di questo capitolo.","Meraviglioso! La Parola di Dio mette radici nella vostra casa."]},"couple":{"q":["Che cosa dice questo brano a noi come coppia?","Dopo ogni litigio prendiamo le distanze. Come può uno di noi fare il primo passo verso la riconciliazione?","Come posso dire ciò che sento perché il mio partner mi ascolti?","Il mio partner mi ha ferito. Devo davvero perdonare?","Non siamo d’accordo sui soldi e sulle faccende di casa. Che cosa facciamo?","Come possiamo pregare insieme e avvicinarci a Dio come coppia?","Nel trambusto quotidiano ci siamo allontanati. Come ritroviamo la strada l’uno verso l’altra?","Scrivici, per favore, una breve preghiera di benedizione per il nostro matrimonio."],"fu":["Dialogo","Perdono","Vicinanza","Un solo cuore","Leggere insieme","Preghiera"],"rw":["Avete letto insieme tutto il libro di {nm}!","Una coppia che si avvicina insieme alla Parola di Dio sta su un fondamento solido."],"res":["Nessun problema, ci andiamo con calma. Rileggetelo insieme una sera.","Molto bene! Avete colto entrambi l’essenziale di questo capitolo.","Meraviglioso! La Parola di Dio mette radici nel vostro matrimonio."]},"pastor":{"q":["Che cosa mi dice questo brano nel servizio al Signore?","Aiutami a trovare uno schema di predica e un’introduzione per questo brano.","Sono sull’orlo dell’esaurimento. Quale conforto mi dà questo brano?","Come affronto le critiche e i fraintendimenti nella comunità?","Che cosa dice questo brano sul guidare un gruppo di collaboratori con un solo cuore?","Come curo il mio rapporto personale con Dio in mezzo a un ministero così intenso?","Come mi prendo cura dei deboli, dei feriti e di chi si è allontanato dalla comunità?","Scrivimi, per favore, una breve preghiera di intercessione per la comunità e i miei collaboratori."],"fu":["Predicazione","Cura pastorale","Squadra","Riposo","Combattimento spirituale","Intercessione"],"rw":["Hai letto tutto il libro di {nm}!","Restare vicino alla Parola di Dio in mezzo a un ministero intenso è la radice più profonda di ogni servizio pastorale."],"res":["Nessun problema, ci andiamo con calma. Rileggilo quando ne avrai l’occasione.","Molto bene! Hai colto l’essenziale di questo capitolo.","Meraviglioso! La Parola di Dio nutre prima il pastore e poi scorre verso il gregge."]}};
